package runner

import (
	"bytes"
	"encoding/json"
	"strings"

	"github.com/hoxiai/hoxi/internal/subproc"
)

// Tool titles generated by OpenCode can omit the leading comment character.
// Only display fields are cleaned here; execution arguments, tool IDs and real
// output must retain their original values for precise stopping and inspection.
func cleanOpenCodeToolDisplayText(raw string) string {
	if strings.HasPrefix(strings.TrimLeft(raw, " \t"), "hoxi-stop:") {
		raw = "# " + strings.TrimLeft(raw, " \t")
	}
	return subproc.RepairUTF8Mojibake(unwrapSandboxCommand(raw))
}

func cleanOpenCodeDisplayFields(fields map[string]interface{}, keys ...string) bool {
	changed := false
	for _, key := range keys {
		if raw, ok := fields[key].(string); ok {
			if cleaned := cleanOpenCodeToolDisplayText(raw); cleaned != raw {
				fields[key] = cleaned
				changed = true
			}
		}
	}
	return changed
}

func openCodeDisplayCommand(input map[string]interface{}) string {
	command := firstString(input["command"], input["cmd"])
	return strings.TrimSpace(strings.SplitN(command, "\n", 2)[0])
}

// stripOpenCodeStopMarker normalizes live managed tool parts before they reach
// Hoxi's store. The sandbox plugin still executes the original tagged command.
func stripOpenCodeStopMarker(part *MessagePart) {
	if part == nil || part.Type != "tool" || part.State == nil {
		return
	}
	state := part.State
	if state.Output != "" {
		state.Output = subproc.RepairUTF8Mojibake(state.Output)
	}
	if state.Error != "" {
		state.Error = subproc.RepairUTF8Mojibake(state.Error)
	}
	for _, key := range []string{"output", "stdout", "stderr"} {
		if raw, ok := state.Metadata[key].(string); ok && raw != "" {
			if repaired := subproc.RepairUTF8Mojibake(raw); repaired != raw {
				state.Metadata[key] = repaired
			}
		}
	}
	if part.Tool != "bash" {
		return
	}
	cleanOpenCodeDisplayFields(state.Input, "command", "cmd", "description")
	cleanOpenCodeDisplayFields(state.Metadata, "command", "cmd", "description", "title")
	if title := cleanOpenCodeToolDisplayText(state.Title); title != state.Title {
		state.Title = title
		if strings.TrimSpace(title) == "" {
			state.Title = openCodeDisplayCommand(state.Input)
		}
	}
}

func containsOpenCodeSanitizeMarker(raw []byte) bool {
	return bytes.Contains(raw, []byte("hoxi-stop:")) ||
		bytes.Contains(raw, []byte("sandbox-exec")) ||
		bytes.Contains(raw, []byte("trap : EXIT")) ||
		bytes.Contains(raw, []byte(toolStoppedNotice)) ||
		bytes.Contains(raw, []byte("DSML")) ||
		bytes.Contains(raw, []byte("</invoke>")) ||
		bytes.Contains(raw, []byte(`\u003c/invoke`)) ||
		bytes.Contains(raw, []byte("</parameter>")) ||
		bytes.Contains(raw, []byte(`\u003c/parameter`))
}

// SanitizeOpenCodeToolJSON cleans tool display fields in upstream message
// histories and events, including old persisted Hoxi histories. It deliberately
// preserves user/assistant text, shell output and unrelated metadata, and keeps
// unmodified payloads byte-identical.
func SanitizeOpenCodeToolJSON(raw []byte) []byte {
	if !containsOpenCodeSanitizeMarker(raw) {
		return raw
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var root interface{}
	if dec.Decode(&root) != nil || !sanitizeOpenCodeToolNode(root) {
		return raw
	}
	if cleaned, err := json.Marshal(root); err == nil {
		return cleaned
	}
	return raw
}

func sanitizeOpenCodeToolNode(node interface{}) bool {
	changed := false
	switch value := node.(type) {
	case []interface{}:
		for _, item := range value {
			changed = sanitizeOpenCodeToolNode(item) || changed
		}
	case map[string]interface{}:
		if value["type"] == "tool" && value["tool"] == "bash" {
			if state, ok := value["state"].(map[string]interface{}); ok {
				input, _ := state["input"].(map[string]interface{})
				meta, _ := state["metadata"].(map[string]interface{})
				changed = cleanOpenCodeDisplayFields(input, "command", "cmd", "description") || changed
				changed = cleanOpenCodeDisplayFields(meta, "command", "cmd", "description", "title") || changed
				if title, ok := state["title"].(string); ok {
					if cleaned := cleanOpenCodeToolDisplayText(title); cleaned != title {
						if strings.TrimSpace(cleaned) == "" {
							cleaned = openCodeDisplayCommand(input)
						}
						state["title"] = cleaned
						changed = true
					}
				}
			}
		} else if value["type"] == "reasoning" {
			if text, ok := value["text"].(string); ok {
				if cleaned, leaked := stripLeakedReasoningToolMarkup(text); leaked && cleaned != text {
					value["text"] = cleaned
					changed = true
				}
			}
		}
		// Traverse protocol envelopes only, never arbitrary tool arguments or
		// outputs that may themselves contain JSON or examples of this marker.
		for _, key := range []string{"payload", "properties", "part", "parts"} {
			changed = sanitizeOpenCodeToolNode(value[key]) || changed
		}
	}
	return changed
}

// SanitizeOpenCodeDisplaySSELine covers both global and directory streams. It
// preserves frame boundaries so it can also run on the raw proxy stream.
func SanitizeOpenCodeDisplaySSELine(line string) string {
	if !strings.HasPrefix(line, "data:") || !containsOpenCodeSanitizeMarker([]byte(line)) {
		return line
	}
	line = sanitizeOpenCodePermissionSSELine(line)
	trimmed := strings.TrimRight(line, "\r\n")
	payload := []byte(strings.TrimSpace(strings.TrimPrefix(trimmed, "data:")))
	cleaned := SanitizeOpenCodeToolJSON(payload)
	if bytes.Equal(payload, cleaned) {
		return line
	}
	return "data: " + string(cleaned) + line[len(trimmed):]
}

func canonicalToolPartFingerprint(p MessagePart) string {
	if p.Type != "tool" || p.State == nil || len(p.State.Input) == 0 {
		return ""
	}
	tool := strings.TrimSpace(p.Tool)
	if tool == "" || doomLoopPollingTools[tool] || doomLoopPollingTools[strings.ToLower(tool)] {
		return ""
	}
	if tool == "bash" {
		cmd := strings.TrimSpace(cleanOpenCodeToolDisplayText(firstString(p.State.Input["command"], p.State.Input["cmd"])))
		if cmd == "" {
			return ""
		}
		workdir := strings.TrimSpace(firstString(p.State.Input["workdir"], p.State.Input["cwd"]))
		return "bash\x00" + workdir + "\x00" + cmd
	}
	rawInput, err := json.Marshal(p.State.Input)
	if err != nil || len(rawInput) == 0 || string(rawInput) == "{}" {
		return ""
	}
	if isDoomLoopPollingCall(tool, rawInput) {
		return ""
	}
	return tool + "\x00" + string(rawInput)
}

// pruneRunawayDuplicateToolParts collapses degenerate duplicate tool-call floods
// within a single assistant message (> runawayDuplicateToolThreshold identical
// tool calls in the same message) down to a single representative part per
// repeated fingerprint, and drops trailing empty-input truncated tool stubs in
// that runaway message. Normal messages are returned untouched.
func pruneRunawayDuplicateToolParts(parts []MessagePart) []MessagePart {
	if len(parts) <= runawayDuplicateToolThreshold {
		return parts
	}
	counts := make(map[string]int)
	chosenIdx := make(map[string]int)
	for i, p := range parts {
		fp := canonicalToolPartFingerprint(p)
		if fp == "" {
			continue
		}
		counts[fp]++
		if prevIdx, exists := chosenIdx[fp]; !exists {
			chosenIdx[fp] = i
		} else if parts[prevIdx].State != nil && parts[prevIdx].State.Status != "completed" &&
			p.State != nil && p.State.Status == "completed" {
			chosenIdx[fp] = i
		}
	}
	hasRunaway := false
	for _, c := range counts {
		if c > runawayDuplicateToolThreshold {
			hasRunaway = true
			break
		}
	}
	if !hasRunaway {
		return parts
	}
	out := make([]MessagePart, 0, len(parts))
	for i, p := range parts {
		if p.Type != "tool" {
			out = append(out, p)
			continue
		}
		fp := canonicalToolPartFingerprint(p)
		if fp == "" {
			if p.State == nil || len(p.State.Input) == 0 {
				continue
			}
			out = append(out, p)
			continue
		}
		if counts[fp] > runawayDuplicateToolThreshold && i != chosenIdx[fp] {
			continue
		}
		out = append(out, p)
	}
	return out
}
